// Shared event handling and items operation utilities for chat / compact streams
import type { StoreApi } from "zustand";
import type { ServerEvent, StoredMessage } from "../runtime/types";
import type { AppState, ChatItem } from "./types";

/** Tool-image composite message (e.g. read loading images; generated by the agent layer to inject model context):
 *  runtime_meta carries a {"format":"tool-attachment"} marker; skipped when rendering during history load.
 *  Old data without the marker is not recognized (displayed as-is). */
export function isToolAttachmentMessage(msg: StoredMessage): boolean {
  if (!msg.runtime_meta) return false;
  try {
    const v = JSON.parse(msg.runtime_meta) as { format?: string };
    return v.format === "tool-attachment";
  } catch {
    return false;
  }
}

/** Extract readable text from an error response */
export async function readError(resp: Response): Promise<string> {
  const text = await resp.text().catch(() => "");
  return text || `HTTP ${resp.status}`;
}

/** Compact completion marker text (align with TUI CompactMarker: count + duration; history restore has no duration, count only) */
export function compactMarkerText(count: number, totalMs?: number): string {
  const secs =
    totalMs !== undefined && totalMs > 0
      ? ` · ${Math.max(1, Math.round(totalMs / 1000))}s`
      : "";
  return `已压缩 ${count} 条消息${secs}`;
}

export function itemOps(
  get: StoreApi<AppState>["getState"],
  set: StoreApi<AppState>["setState"],
) {
  const items = get().items;
  const push = (item: ChatItem) => set((s) => ({ items: [...s.items, item] }));
  const patchLast = (patch: (item: ChatItem) => ChatItem) => {
    if (items.length === 0) return;
    set((s) => ({
      items: [...s.items.slice(0, -1), patch(s.items[s.items.length - 1]!)],
    }));
  };
  return { items, push, patchLast };
}

export type ItemOps = ReturnType<typeof itemOps>;

/** Shared event branches for chat/compact streams; returns true if consumed.
 *  SessionStarted is handled by run-sink (session binding + running state). */
export function handleSharedEvent(
  event: ServerEvent,
  ops: ItemOps,
  set: StoreApi<AppState>["setState"],
): boolean {
  switch (event.type) {
    case "Notice":
      ops.push({ kind: "notice", text: event.text });
      return true;
    case "CompactStart":
      // Align with TUI: keep only one status line while compacting; don't show the summary stream
      ops.push({ kind: "compacting", text: event.text });
      return true;
    case "CompactComplete":
      // Align with TUI: replace the whole status line with the completion marker (count + duration)
      ops.patchLast(() => ({
        kind: "compact-marker",
        text: compactMarkerText(event.compacted_count, event.total_ms),
      }));
      // Align with TUI set_session_usage(estimated, 0): refresh context usage immediately
      // (context fields only; the top-bar cumulative accounting is unaffected by compaction)
      if (event.context_tokens != null) {
        set({
          contextPromptTokens: event.context_tokens,
          contextCompletionTokens: 0,
        });
      }
      return true;
    case "Error": {
      // Replace the compacting status line in place with the error (matching TUI CompactError replace semantics); append as usual otherwise
      const errItem: ChatItem = { kind: "error", text: event.message };
      if (ops.items[ops.items.length - 1]?.kind === "compacting") {
        ops.patchLast(() => errItem);
      } else {
        ops.push(errItem);
      }
      return true;
    }
    default:
      return false;
  }
}
